questions.uml_mutation:
class DoorState {
    <<enumeration>>
    OPEN
    CLOSED
}
class Door {
    +openDoor()
    +closeDoor()
}
Door --> DoorState : state

class Button {
    <<abstract>>
}
class HallButton {
    -Direction buttonDirection
}
class CarButton {
    -int destinationFloor
}
Button <|-- HallButton
Button <|-- CarButton

class ElevatorSystem {
    -String buildingName
}
ElevatorSystem "1" o-- "*" ElevatorCar : manages_fleet

class DispatchStrategy {
    <<interface>>
    +selectCar(ElevatorCar[] cars, Request req) : ElevatorCar
}
class ShortestSeekTimeStrategy {
    +selectCar(ElevatorCar[] cars, Request req) : ElevatorCar
}
DispatchStrategy <|.. ShortestSeekTimeStrategy
ElevatorSystem --> DispatchStrategy : utilizes

class Request {
    -int originFloor
    -int destinationFloor
    -Direction direction
}
DispatchStrategy ..> Request : evaluates

class FloorObserver {
    <<interface>>
    +onFloorChanged(int newFloor, Direction dir)
}
class DisplayScreen {
    +onFloorChanged(int newFloor, Direction dir)
}
FloorObserver <|.. DisplayScreen
ElevatorCar --> FloorObserver : notifies

class ElevatorController {
    -ElevatorController instance$
    +getInstance()$ : ElevatorController
}
ElevatorController *-- ElevatorSystem : delegates

class ElevatorController {
    -ElevatorController instance$
    +getInstance()$ : ElevatorController
}
class RequestQueue {
    +enqueue(Request req)
    +dequeue() : Request
}
ElevatorController *-- ElevatorSystem : delegates
ElevatorController *-- RequestQueue : buffers_in
